// parseDays parses a whole number of days of 24 hours ("30d"), optionally
// followed by Go duration syntax ("1d12h").
func parseDays(v string) (time.Duration, bool) {
	i := strings.IndexByte(v, 'd')
	if i < 0 {
		return 0, false
	}
	n, err := strconv.Atoi(v[:i])
	if err != nil {
		return 0, false
	}
	d := time.Duration(n) * 24 * time.Hour
	if rest := v[i+1:]; rest != "" {
		r, err := time.ParseDuration(rest)
		if err != nil {
			return 0, false
		}
		d += r
	}
	return d, true
}
